#pragma once
#include <math.h>
#include "sps_types.h"
namespace sps{inline real eval5(const Poly5&p,real u){return (((((p.c[5]*u+p.c[4])*u+p.c[3])*u+p.c[2])*u+p.c[1])*u+p.c[0]);}inline real eval3(const Poly3&p,real u){return (((p.c[3]*u+p.c[2])*u+p.c[1])*u+p.c[0]);}inline Quat qn(Quat q){real n=sqrt(q.w*q.w+q.x*q.x+q.y*q.y+q.z*q.z);if(n<1e-18)return {1,0,0,0};real inv=1.0/n;return {q.w*inv,q.x*inv,q.y*inv,q.z*inv};}inline sps::Quat qslerp(Quat a,Quat b,real t){a=qn(a);b=qn(b);real dot=a.w*b.w+a.x*b.x+a.y*b.y+a.z*b.z; if(dot<0){b={-b.w,-b.x,-b.y,-b.z}; dot=-dot;} if(dot>0.9995){Quat q{a.w+(b.w-a.w)*t,a.x+(b.x-a.x)*t,a.y+(b.y-a.y)*t,a.z+(b.z-a.z)*t}; return qn(q);}real th=acos(dot);real s0=sin((1-t)*th)/sin(th);real s1=sin(t*th)/sin(th);return {a.w*s0+b.w*s1,a.x*s0+b.x*s1,a.y*s0+b.y*s1,a.z*s0+b.z*s1};}inline Quat qsquad(const Quat&q0,const Quat&qa,const Quat&qb,const Quat&q1,real t){auto s1=qslerp(q0,q1,t);auto s2=qslerp(qa,qb,t);return qslerp(s1,s2,2*t*(1-t));}inline Pose eval_pose(const Segment&s,real u){Pose o; o.p={eval5(s.px,u),eval5(s.py,u),eval5(s.pz,u)}; o.q=qsquad(s.q0,s.qa,s.qb,s.q1,u); return o;}}
